        let out = digits;

        if (digits.length > 1) {
            out = digits[0] + '(' + digits.slice(1, 4);
        }
        if (digits.length >= 4) {
            out += ')' + digits.slice(4, 7);
        }
        if (digits.length >= 7) {
            out += '-' + digits.slice(7, 9);
